BEGIN;
SELECT set_config('request.jwt.claim.sub','10000000-0000-4000-a000-000000000001',true);
DO $$ DECLARE supplier uuid:=gen_random_uuid(); auto_supplier uuid:=gen_random_uuid(); explicit_supplier uuid:=gen_random_uuid(); pr_supplier uuid:=gen_random_uuid(); psa_category uuid:=gen_random_uuid(); pr_category uuid:=gen_random_uuid(); q uuid; evidence_q uuid; result jsonb; psa uuid:='00000000-0000-4000-a000-000000000001'; pr uuid:='e0b3ac8e-97a5-4fb1-a2b0-53f65125d114'; BEGIN
INSERT INTO companies(id,nome,is_supplier,tax_country,foreign_tax_id) VALUES(supplier,'[DISPOSABLE BUG FIXTURE] PSA only',true,'GB','GBFIXTURE01'),(auto_supplier,'[DISPOSABLE BUG FIXTURE] auto supplier',true,'GB','GBFIXTURE02'),(explicit_supplier,'[DISPOSABLE BUG FIXTURE] explicit supplier',true,'GB','GBFIXTURE03'),(pr_supplier,'[DISPOSABLE BUG FIXTURE] Rioja only',true,'GB','GBFIXTURE04');
INSERT INTO financial_classifications(id,entity_id,code,name_en,name_pt,level,financial_nature) VALUES(psa_category,psa,'FIX.PSA','Fixture','Fixture','category','operational'),(pr_category,pr,'FIX.PR','Fixture','Fixture','category','operational');
INSERT INTO financial_document_review_queue(source_file_url,entity_id,matched_supplier_id) VALUES('fixture/psa-history.jpg',psa,supplier);
INSERT INTO financial_document_review_queue(id,source_file_url,entity_id,intake_route,intake_type,extracted_date,extracted_amount,suggested_classification_id,marked_unpaid) VALUES(gen_random_uuid(),'fixture/psa-confirm.jpg',psa,'purchases','fatura_compra','2026-11-02',10,psa_category,true) RETURNING id INTO q;
result:=fin_confirm_queue_item(q,jsonb_build_object('counterparty_id',supplier));
IF (result->>'ok')::boolean IS DISTINCT FROM true OR (SELECT status::text FROM financial_document_review_queue WHERE id=q)<>'approved' THEN RAISE EXCEPTION 'PSA confirm failed'; END IF;
RAISE NOTICE 'PASS: PSA-only supplier confirmation';
INSERT INTO financial_document_review_queue(source_file_url,entity_id,intake_route,intake_type,extracted_date,extracted_amount,suggested_classification_id,marked_unpaid,matched_supplier_id) VALUES('fixture/auto.jpg',psa,'purchases','fatura_compra','2026-11-02',10,psa_category,true,auto_supplier) RETURNING id INTO q;
result:=fin_confirm_queue_item(q); IF (result->>'ok')::boolean IS DISTINCT FROM true THEN RAISE EXCEPTION 'Auto matched failed'; END IF;
RAISE NOTICE 'PASS: auto-matched supplier on same queue';
INSERT INTO financial_document_review_queue(source_file_url,entity_id,intake_route,intake_type,extracted_date,extracted_amount,suggested_classification_id,marked_unpaid) VALUES('fixture/explicit.jpg',psa,'purchases','fatura_compra','2026-11-02',10,psa_category,true) RETURNING id INTO q;
result:=fin_confirm_queue_item(q,jsonb_build_object('link_counterparty_id',explicit_supplier)); IF NOT EXISTS(SELECT 1 FROM finance_entity_companies WHERE company_id=explicit_supplier AND entity_id=psa) THEN RAISE EXCEPTION 'Explicit link failed'; END IF;
RAISE NOTICE 'PASS: explicit link confirmation';
INSERT INTO finance_entity_companies(entity_id,company_id) VALUES(pr,pr_supplier);
INSERT INTO financial_document_review_queue(source_file_url,entity_id,intake_route,intake_type,extracted_date,extracted_amount,suggested_classification_id,marked_unpaid) VALUES('fixture/psa-pr-block.jpg',psa,'purchases','fatura_compra','2026-11-02',10,psa_category,true) RETURNING id INTO q;
BEGIN PERFORM fin_confirm_queue_item(q,jsonb_build_object('counterparty_id',pr_supplier)); RAISE EXCEPTION 'Cross entity incorrectly allowed'; EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'Counterparty not visible in this entity' THEN RAISE; END IF; END;
RAISE NOTICE 'PASS: PSA queue refuses Rioja-only supplier (multi-entity admin)';
PERFORM set_config('request.jwt.claim.sub','10000000-0000-4000-a000-000000000002',true);
INSERT INTO financial_document_review_queue(source_file_url,entity_id,intake_route,intake_type,extracted_date,extracted_amount,suggested_classification_id,marked_unpaid) VALUES('fixture/pr-block.jpg',pr,'purchases','fatura_compra','2026-11-02',10,pr_category,true) RETURNING id INTO q;
BEGIN PERFORM fin_confirm_queue_item(q,jsonb_build_object('counterparty_id',supplier)); RAISE EXCEPTION 'Rioja improperly saw PSA'; EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'Counterparty not visible in this entity' THEN RAISE; END IF; END;
IF fin_company_visible(supplier) THEN RAISE EXCEPTION 'PSA supplier exposed through company visibility'; END IF;
RAISE NOTICE 'PASS: Rioja user cannot confirm or see PSA-only supplier';
result:=fin_confirm_queue_item(q,jsonb_build_object('counterparty_id',pr_supplier)); IF (result->>'ok')::boolean IS DISTINCT FROM true THEN RAISE EXCEPTION 'Same-entity link failed'; END IF;
RAISE NOTICE 'PASS: Rioja entity-linked supplier confirmation';
END $$;
ROLLBACK;
